import{_ as a,a0 as r,w as l,s as d,I as p,x as t,a1 as n,A as o,ao as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"试试Linux下的ip命令，ifconfig已经过时了 | LCTT x X-CMD","titleTemplate":false,"description":"试试Linux下的ip命令，ifconfig已经过时了 | LCTT (201406) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"试试Linux下的ip命令，ifconfig已经过时了 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"试试Linux下的ip命令，ifconfig已经过时了 | LCTT (201406) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201406/Start Practising Linux ip command and Avoid the Habit of Using ifconfig","title":"试试Linux下的ip命令，ifconfig已经过时了","tag":"201406","desc":""},"relativePath":"201406/Start Practising Linux ip command and Avoid the Habit of Using ifconfig.md","filePath":"[post].md"}'),u={name:"201406/Start Practising Linux ip command and Avoid the Habit of Using ifconfig.md"};function m(g,i,c,f,h,x){const e=r("Link");return l(),d("div",null,[i[16]||(i[16]=p("h1",{id:"试试linux下的ip命令-ifconfig已经过时了",tabindex:"-1"},[t("试试Linux下的ip命令，ifconfig已经过时了 "),p("a",{class:"header-anchor",href:"#试试linux下的ip命令-ifconfig已经过时了","aria-label":"Permalink to “试试Linux下的ip命令，ifconfig已经过时了”"},"​")],-1)),i[17]||(i[17]=p("p",null,[t("linux的"),p("strong",null,"ip"),t("命令和"),p("strong",null,"ifconfig"),t("类似，但前者功能更强大，并旨在取代后者。使用ip命令，只需一个命令，你就能很轻松地执行一些网络管理任务。ifconfig是net-tools中已被废弃使用的一个命令，许多年前就已经没有维护了。iproute2套件里提供了许多增强功能的命令，ip命令即是其中之一。")],-1)),i[18]||(i[18]=p("p",null,[p("img",{src:"http://linoxide.com/wp-content/uploads/2014/05/Linux-Nettools-vs-Iproute2.png",alt:"Net tools vs Iproute2"})],-1)),p("p",null,[i[1]||(i[1]=t("要安装ip，请",-1)),n(e,{href:"http://www.linuxgrill.com/anonymous/iproute2/NEW-OSDL/"},{default:o(()=>[...i[0]||(i[0]=[t("点击这里",-1)])]),_:1}),i[2]||(i[2]=t("下载",-1)),i[3]||(i[3]=p("strong",null,"iproute2套装工具",-1)),i[4]||(i[4]=t(" 。不过，大多数Linux发行版已经预装了iproute2工具。",-1))]),i[19]||(i[19]=s(`<p>你也可以使用git命令来下载最新源代码来编译：</p><pre><code>$ git clone https://kernel.googlesource.com/pub/scm/linux/kernel/git/shemminger/iproute2.git
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/04/iproute2-git-clone.png" alt="iproute2 git clone"></p><h3 id="设置和删除ip地址" tabindex="-1">设置和删除Ip地址 <a class="header-anchor" href="#设置和删除ip地址" aria-label="Permalink to “设置和删除Ip地址”">​</a></h3><p>要给你的机器设置一个IP地址，可以使用下列ip命令：</p><pre><code>$ sudo ip addr add 192.168.0.193/24 dev wlan0
</code></pre><p>请注意IP地址要有一个后缀，比如/24。这种用法用于在无类域内路由选择（CIDR）中来显示所用的子网掩码。在这个例子中，子网掩码是255.255.255.0。</p><p>在你按照上述方式设置好IP地址后，需要查看是否已经生效。</p><pre><code>$ ip addr show wlan0
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/04/set-ip-address.png" alt="set ip address"></p><p>你也可以使用相同的方式来删除IP地址，只需用del代替add。</p><pre><code>$ sudo ip addr del 192.168.0.193/24 dev wlan0
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/04/delete-ip-address.png" alt="delete ip address"></p><h3 id="列出路由表条目" tabindex="-1">列出路由表条目 <a class="header-anchor" href="#列出路由表条目" aria-label="Permalink to “列出路由表条目”">​</a></h3><p>ip命令的路由对象的参数还可以帮助你查看网络中的路由数据，并设置你的路由表。第一个条目是默认的路由条目，你可以随意改动它。</p><p>在这个例子中，有几个路由条目。这个结果显示有几个设备通过不同的网络接口连接起来。它们包括WIFI、以太网和一个点对点连接。</p><pre><code>$ ip route show
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/04/ip-route-show.png" alt="ip route show"></p><p>假设现在你有一个IP地址，你需要知道路由包从哪里来。可以使用下面的路由选项（译注：列出了路由所使用的接口等）：</p><pre><code>$ ip route get 10.42.0.47
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/04/ip-route-get.png" alt="ip route get"></p><h3 id="更改默认路由" tabindex="-1">更改默认路由 <a class="header-anchor" href="#更改默认路由" aria-label="Permalink to “更改默认路由”">​</a></h3><p>要更改默认路由，使用下面ip命令：</p><pre><code>$ sudo ip route add default via 192.168.0.196
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/04/default-route.png" alt="default route"></p><h3 id="显示网络统计数据" tabindex="-1">显示网络统计数据 <a class="header-anchor" href="#显示网络统计数据" aria-label="Permalink to “显示网络统计数据”">​</a></h3><p>使用ip命令还可以显示不同网络接口的统计数据。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/04/ip-statistics-all-interfaces.png" alt="ip statistics all interfaces"></p><p>当你需要获取一个特定网络接口的信息时，在网络接口名字后面添加选项<strong>ls</strong>即可。使用多个选项<strong>-s</strong>会给你这个特定接口更详细的信息。特别是在排除网络连接故障时，这会非常有用。</p><pre><code>$ ip -s -s link ls p2p1
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/04/ip-link-statistics-.png" alt="ip link statistics"></p><h3 id="arp条目" tabindex="-1">ARP条目 <a class="header-anchor" href="#arp条目" aria-label="Permalink to “ARP条目”">​</a></h3><p>地址解析协议（ARP）用于将一个IP地址转换成它对应的物理地址，也就是通常所说的MAC地址。使用ip命令的neigh或者neighbour选项，你可以查看接入你所在的局域网的设备的MAC地址。</p><pre><code>$ ip neighbour
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/04/ip-neighbour.png" alt="ip neighbour"></p><h3 id="监控netlink消息" tabindex="-1">监控netlink消息 <a class="header-anchor" href="#监控netlink消息" aria-label="Permalink to “监控netlink消息”">​</a></h3><p>也可以使用ip命令查看netlink消息。monitor选项允许你查看网络设备的状态。比如，所在局域网的一台电脑根据它的状态可以被分类成REACHABLE或者STALE。使用下面的命令：</p><pre><code>$ ip monitor all
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/04/ip-monitor-all.png" alt="ip monitor all"></p><h3 id="激活和停止网络接口" tabindex="-1">激活和停止网络接口 <a class="header-anchor" href="#激活和停止网络接口" aria-label="Permalink to “激活和停止网络接口”">​</a></h3><p>你可以使用ip命令的up和down选项来激某个特定的接口，就像ifconfig的用法一样。</p><p>在这个例子中，当ppp0接口被激活和在它被停止和再次激活之后，你可以看到相应的路由表条目。这个接口可能是wlan0或者eth0。将ppp0更改为你可用的任意接口即可。</p><pre><code>$ sudo ip link set ppp0 down

$ sudo ip link set ppp0 up
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/04/ip-link-set-up-and-down.png" alt="ip link set up and down"></p><h3 id="获取帮助" tabindex="-1">获取帮助 <a class="header-anchor" href="#获取帮助" aria-label="Permalink to “获取帮助”">​</a></h3><p>当你陷入困境，不知道某一个特定的选项怎么用的时候，你可以使用help选项。man页面并不会提供许多关于如何使用ip选项的信息，因此这里就是获取帮助的地方。</p><p>比如，想知道关于route选项更多的信息：</p><pre><code>$ ip route help
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/04/ip-route-help.png" alt="ip route help"></p><h3 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h3><p>对于网络管理员们和所有的Linux使用者们，ip命令是必备工具。是时候抛弃ifconfig命令了，特别是当你写脚本时。</p><hr>`,52)),p("p",null,[i[6]||(i[6]=t("via: ",-1)),n(e,{href:"http://linoxide.com/linux-command/use-ip-command-linux/"},{default:o(()=>[...i[5]||(i[5]=[t("http://linoxide.com/linux-command/use-ip-command-linux/",-1)])]),_:1})]),p("p",null,[i[9]||(i[9]=t("译者：",-1)),n(e,{href:"https://github.com/KayGuoWhu"},{default:o(()=>[...i[7]||(i[7]=[t("KayGuoWhu",-1)])]),_:1}),i[10]||(i[10]=t(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:o(()=>[...i[8]||(i[8]=[t("wxy",-1)])]),_:1})]),p("p",null,[i[13]||(i[13]=t("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...i[11]||(i[11]=[t("LCTT",-1)])]),_:1}),i[14]||(i[14]=t(" 原创翻译，",-1)),n(e,{href:"http://linux.cn/"},{default:o(()=>[...i[12]||(i[12]=[t("Linux中国",-1)])]),_:1}),i[15]||(i[15]=t(" 荣誉推出",-1))])])}const P=a(u,[["render",m]]);export{k as __pageData,P as default};
